import time
from argparse import ArgumentParser
from copy import deepcopy
from pathlib import Path

import numpy as np
import trimesh
import viser
from scipy.spatial.transform import Rotation as R

# Constants
AXES_LENGTH = 0.0
AXES_RADIUS = 0.0


def xyzw_to_wxyz(xyzw: np.ndarray) -> np.ndarray:
    assert xyzw.shape[-1] == 4, f"Expected xyzw to be (..., 4), got {xyzw.shape}"
    return xyzw[..., [3, 0, 1, 2]]


def wxyz_to_xyzw(wxyz: np.ndarray) -> np.ndarray:
    assert wxyz.shape[-1] == 4, f"Expected wxyz to be (..., 4), got {wxyz.shape}"
    return wxyz[..., [1, 2, 3, 0]]


def viser_visualize_cuboids_interactive(scales: np.ndarray):
    # The goal of this function is to allow the user to visualize cuboids interactively in viser.
    N, D = scales.shape
    print(f"N: {N}, D: {D}")
    assert N > 0, f"Expected N to be greater than 0, got {N}"
    assert D == 3, f"Expected D to be 3, got {D}"

    # BOX_SCALE = 0.05
    BOX_SCALE = 0.04
    box_scales = scales * BOX_SCALE

    # #########################################################
    # Create scene
    # #########################################################

    # Create server
    server = viser.ViserServer()

    # Create ground
    server.scene.add_grid("/ground", width=2, height=2, cell_size=0.1)

    # Create robot
    from isaacgymenvs.utils.utils import get_repo_root_dir
    from viser.extras import ViserUrdf
    robot_urdf_path = get_repo_root_dir() / "assets/urdf/kuka_allegro_description/iiwa14_left_sharpa_adjusted_restricted.urdf"
    assert robot_urdf_path.exists(), f"robot_urdf_path not found: {robot_urdf_path}"

    server.scene.add_frame(
        "/robot/state",
        position=(0, 0.8, 0),
        wxyz=(1, 0, 0, 0),
        show_axes=False,
    )
    robot_viser = ViserUrdf(
        server, robot_urdf_path, root_node_name="/robot/state"
    )
    HOME_JOINT_POS_IIWA = np.array([-1.571, 1.571, -0.000, 1.376, -0.000, 1.485, 1.308])
    HOME_JOINT_POS_SHARPA = np.zeros(22)
    HOME_JOINT_POS = np.concatenate([HOME_JOINT_POS_IIWA, HOME_JOINT_POS_SHARPA])
    robot_viser.update_cfg(HOME_JOINT_POS)

    LOAD_TABLE = True
    if LOAD_TABLE:
        table_urdf_path = get_repo_root_dir() / "assets/urdf/table_narrow.urdf"
        assert table_urdf_path.exists(), (
            f"table_urdf_path not found: {table_urdf_path}"
        )

        server.scene.add_frame(
            "/table",
            position=(0.0, 0.0, 0.38),
            wxyz=(1, 0, 0, 0),
            show_axes=False,
        )
        BLACK_RGBA_TRANSLUCENT = (0, 0, 0, 0.5)
        table_viser = ViserUrdf(
            server,
            table_urdf_path,
            root_node_name="/table",
            mesh_color_override=BLACK_RGBA_TRANSLUCENT,
        )

    # Load mesh
    # Create a 1m x 1m x 1m box mesh using trimesh
    mesh_origin_frame = server.scene.add_frame(
        name="/mesh_frame",
        position=(0, 0, 0.53 + 0.05),
        wxyz=(1, 0, 0, 0),
        show_axes=True,
        axes_length=AXES_LENGTH,
        axes_radius=AXES_RADIUS,
    )

    mesh = trimesh.creation.box(extents=box_scales[0])
    mesh_vis = server.scene.add_mesh_simple(name="/mesh_frame/mesh", vertices=mesh.vertices, faces=mesh.faces)

    def get_slider_label(idx: int) -> str:
        """Get slider label with current box_scale value."""
        box_scale = box_scales[idx]
        return f"Idx {idx} (box_scale: [{box_scale[0]:.3f}, {box_scale[1]:.3f}, {box_scale[2]:.3f}])"

    with server.gui.add_folder("Scale Slider"):
        # Mesh scale state
        initial_idx = 0
        scale_slider = server.gui.add_slider(
            label=get_slider_label(initial_idx),
            min=0,
            max=N-1,
            step=1,
            initial_value=initial_idx,
        )

    @scale_slider.on_update
    def _(_):
        nonlocal mesh, mesh_vis
        mesh_vis.remove()
        idx = int(scale_slider.value)
        print(f"Changing idx = {idx}, box_scales[idx] = {box_scales[idx]}")
        scale_slider.label = get_slider_label(idx)
        mesh = trimesh.creation.box(extents=box_scales[idx])
        mesh_vis = server.scene.add_mesh_simple(name="/mesh_frame/mesh", vertices=mesh.vertices, faces=mesh.faces)

    while True:
        print(
            f"scale_slider.value = {scale_slider.value}"
        )
        time.sleep(1.0)
        # breakpoint()


